const sharedSpecialties = require('../shared/specialties.js');   // Class Loadouts S1: the ONE class catalog — no hardcoded class prose here
// the specialist classes as {id, tagline}, composed from the shared catalog so team.summon's class list +
// the [ORCHESTRATION] teamNote never drift from the Recruitment Bay (single source of truth).
const SPECIALIST_CLASSES = (sharedSpecialties.BUILTINS || []).map(s => ({ id: s.id, tagline: s.tagline || '' }));

// ---- Skynet→StarNet env back-compat ------------------------------------------------------------
// The project was renamed Skynet → StarNet; its env vars moved SKYNET_* → STARNET_*. ENV() reads the
// NEW name first and falls back to the LEGACY one, so existing launch configs / shells / the desktop
// shell keep working unchanged. Membership test (not truthiness) so a deliberately-empty STARNET_X
// still wins over a set SKYNET_X — preserving each downstream var's exact empty-vs-unset semantics.
function ENV(suffix) { const k = 'STARNET_' + suffix; return (k in process.env) ? process.env[k] : process.env['SKYNET_' + suffix]; }

const PORT = Number(ENV('PORT') || process.env.PORT) || 8787;
const API_TOKEN = String(ENV('API_TOKEN') || crypto.randomBytes(32).toString('hex'));
// DEV fast-path (the `npm run dev:seed` launcher sets this): when on, the served index.html carries a small
// boot payload (window.__STARNET_DEV__ = {model, prov}) so a fresh browser origin auto-resumes the server-
// seeded save with no connect screen / awakening. Holds NO secret — the API key stays in runtimeKey. Never
// set in a packaged build, so this is inert in shipping. Loopback-only like the rest of the server.
const DEV_MODE = /^(1|true|yes|on)$/i.test(String(ENV('DEV') || '').trim());
// Are we running under the real desktop shell (Tauri)? Only then is the OS keychain reachable (through the
// parent process), so only then do channel bot tokens live in the keychain instead of plaintext secrets.json.
// The bare sidecar (npm start / tests / headless deploy) never sets this and HONESTLY keeps the plaintext path.
const DESKTOP_SHELL = /^(1|true|yes|on)$/i.test(String(ENV('DESKTOP_SHELL') || '').trim());
// API auth/guard DECISIONS live in the unit-tested ./apiauth.js (full threat model documented there);
// index.js keeps only the thin res-writing wrappers below. Hardened posture: EVERY /api/* route now requires
// the per-launch token (GET data routes included) except a small header-less set. Native media/file loads
// can pass the same token as ?token= on /api/file only; all other fetch-driven calls use the custom header.
const apiauth = require('./apiauth.js');
const { isAllowedApiOrigin, isAllowedHost, requiresApiToken, TAURI_ORIGINS } = apiauth;
function applyApiCors(req, res) {
  const origin = String(req.headers.origin || '');
  if (origin && isAllowedApiOrigin(origin, PORT)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Vary', 'Origin');
  }
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,DELETE,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type,X-StarNet-Token,X-Skynet-Token');   // accept the legacy header name too (old Tauri shell)
  res.setHeader('Access-Control-Max-Age', '600');
}
function rejectApi(req, res) {
  if (!isAllowedHost(req.headers.host)) { res.writeHead(403); res.end('forbidden host'); return true; }
  if (!isAllowedApiOrigin(String(req.headers.origin || ''), PORT)) { res.writeHead(403); res.end('forbidden origin'); return true; }
  return false;
}
function rejectBadApiToken(req, res) {
  if (!requiresApiToken(req)) return false;
  if (apiauth.apiTokenOk(req, API_TOKEN)) return false;
  // Some browser surfaces provably cannot attach custom headers: native media/link loads (GET/HEAD /api/file)
  // and the unload save beacon (POST /api/save — navigator.sendBeacon, the last debounced save on close).
  // Those exact routes accept the SAME per-launch token in the query string; the matrix lives in apiauth so
  // it stays a tested, deliberately tiny escape hatch.
  if (apiauth.queryTokenRoute(req) && apiauth.queryTokenOk(req, API_TOKEN)) return false;
  res.writeHead(403); res.end('forbidden token'); return true;
}
// Desktop build: live BYOK keys are seeded from the OS keychain via env at spawn, and updated
// in place via the token-guarded POST /api/key (the parent shell pushes changes; no restart).
// runtimeKey remains the OpenRouter back-compat alias for older routes/tool shims.
const runtimeKeys = Object.create(null);
const runtimeKeyPools = Object.create(null);   // provider id -> alternate keys; never shared across providers
const runtimeBaseUrls = Object.create(null);
let runtimeKey = String(ENV('OPENROUTER_KEY') || '').trim();
if (runtimeKey) runtimeKeys.openrouter = runtimeKey;
// OpenRouter base URL override (env SKYNET_OPENROUTER_BASE). Default undefined -> the provider's own
// https://openrouter.ai/api/v1. Lets a user point at an OR-compatible proxy, and lets the boot+run E2E aim
// the provider at a local mock so the real streaming path is tested end-to-end without a live key.
const OPENROUTER_BASE = String(ENV('OPENROUTER_BASE') || '').trim() || undefined;
const FRONTEND = path.resolve(__dirname, '..', 'frontend');
// Class Loadouts S1: the browser needs the SHARED catalog (shared/specialties.js) as a <script>, but the
// static server jails to FRONTEND (a /../shared request is 403). Serve the shared/ dir through a narrow,
// read-only, .js-only allowlist so the browser + the desktop bundle (which ships ../shared as a resource)
// can load it without escaping into arbitrary repo files. Path-jailed to SHARED exactly like FRONTEND.
const SHARED = path.resolve(__dirname, '..', 'shared');
// the agent workspaces + their protected siblings (notebook/ledger/permissions/channels). SKYNET_WORKSPACES
// wins (the desktop shell + isolated tests set it); otherwise resolve a PER-USER, writable OS app-data dir.
// CRITICAL for a packaged install: NEVER default under __dirname — a shipped app lives in read-only Program
// Files, so writing beside the .js source EACCES-fails on first boot and silently kills ALL persistence
// (ledger/memory/secrets/cron) and degrades every permission grant to a deny. App-data is always writable.
function defaultWorkspaces() {
  if (process.platform === 'darwin') {
    // Match Tauri app.path().app_data_dir() exactly. Older manual sidecars used ~/.local/share/StarNet;
    // that location remains a recovery candidate, never a second canonical station.
    return path.join(os.homedir() || '.', 'Library', 'Application Support', 'ai.skynet.harness', 'workspaces');
  }
  const base = process.env.LOCALAPPDATA || process.env.APPDATA            // Windows: %LOCALAPPDATA% (machine-local app data)
    || process.env.XDG_DATA_HOME                                          // Linux XDG
    || path.join(os.homedir() || '.', '.local', 'share');                 // POSIX fallback
  // Skynet→StarNet rename back-compat: prefer the NEW dir; if it doesn't exist yet but the OLD one does, keep
  // using the old one IN PLACE (no move) so existing data is never lost and any old-code process that still
  // looks for \Skynet\ keeps sharing the same data (no split-brain). Fresh installs land under \StarNet\.
  const neu = path.join(base, 'StarNet', 'workspaces');
  const old = path.join(base, 'Skynet', 'workspaces');   // legacy pre-rename location — read in place, never renamed
  try { if (!fs.existsSync(neu) && fs.existsSync(old)) return old; } catch (_) {}
  return neu;
}
const WORKSPACES = ENV('WORKSPACES') ? path.resolve(ENV('WORKSPACES')) : defaultWorkspaces();
const outputArtifacts = makeOutputArtifacts({ fsp, fs, pathMod: path, root: WORKSPACES, crypto });

const RECOVERY_CANDIDATE_ROOTS = workspaceCandidates({
  path: path, env: process.env, platform: process.platform, homedir: () => os.homedir()
}).concat([path.resolve(__dirname, 'workspaces'), path.resolve(__dirname, '..', 'workspaces')]);

// Recovery activation must precede the owner claim and every store constructor. With no explicit request,
// production may self-heal only one unambiguous valid legacy root; conflicts stay read-only for the picker.
const startupWorkspaceRecovery = workspaceRecovery.applyPendingRecovery({
  fs, path, platform: process.platform, home: os.homedir(), workspaceRoot: WORKSPACES,
  candidateRoots: DEV_MODE ? [] : RECOVERY_CANDIDATE_ROOTS, auto: !DEV_MODE, now: Date.now
});
if (startupWorkspaceRecovery && startupWorkspaceRecovery.lockUnavailable) {
  // A LIVE concurrent process holds the parent-level recovery lock — it may be renaming this very
  // workspace right now. Opening stores here would race that rename, so refuse the boot outright,
  // matching the owner-claim refusal below (same fail-closed semantics, same exit code).
  console.error('✗ StarNet refused to open this workspace because another process is recovering it.');
  console.error('  workspace: ' + WORKSPACES);
  console.error('  safety code: ' + String(startupWorkspaceRecovery.code || 'RECOVERY_LOCK_UNAVAILABLE'));
  console.error('  Close the other StarNet process and retry. StarNet will not risk concurrent writes.');
  process.exit(73);
}
if (startupWorkspaceRecovery && startupWorkspaceRecovery.applied) {
  console.warn('[recovery] restored prior station before opening stores; source preserved, rollback retained=' + !!startupWorkspaceRecovery.rollbackRetained);
} else if (startupWorkspaceRecovery && startupWorkspaceRecovery.ok === false) {
  console.error('[recovery] automatic station recovery failed closed: ' + String(startupWorkspaceRecovery.error || 'unknown error'));
} else if (startupWorkspaceRecovery && startupWorkspaceRecovery.autoSkipped) {
  // workspace-recovery.js already warned with the paths; this second line is the one-glance boot summary.
  console.warn('[recovery] auto recovery skipped (' + String(startupWorkspaceRecovery.code) + '): this workspace is a scratch/temp root, so no real station was ingested.');
}

// DEV/QA must be destructive only inside an explicit scratch profile. A forgotten WORKSPACES override used
// to make a headless audit inherit the Commander's canonical app-data root; that can produce a reset-looking
// last-writer-wins rollback even when no bytes are erased. Block every current + legacy production root here,
// before the owner file or any durable user state is opened. The packaged desktop never enables DEV_MODE.
const devWorkspaceSafety = DEV_MODE
  ? classifyWorkspace(WORKSPACES, { path: path, env: process.env, platform: process.platform, homedir: () => os.homedir() })
  : { protected: false };
if (devWorkspaceSafety.protected) {
  console.error('✗ StarNet refused to run DEV/QA against a canonical user workspace.');
  console.error('  workspace: ' + WORKSPACES);
  console.error('  safety code: DEV_WORKSPACE_PROTECTED');
  console.error('  Set STARNET_WORKSPACES to a dedicated scratch directory and retry.');
  process.exit(74);
}

// DATA-SAFETY INVARIANT: every durable store below assumes exactly one sidecar owns WORKSPACES.
// Claim that root BEFORE pricing cache, runtime knobs, roster, station save, or any other persisted state
// is read. A second writer fails closed; a crash-killed holder is reclaimed only when its PID is provably
// dead (never merely because the claim is old). The desktop shell's uncatchable Windows force-kill leaves
// this file behind by design; the next legitimate boot performs that proven-dead recovery.
const workspaceOwner = makeWorkspaceOwner({ fs: fs, path: path, now: () => Date.now(), bootedAt: makeBootedAt(() => Date.now()) });
const workspaceOwnerClaim = workspaceOwner.acquire(WORKSPACES);
if (!workspaceOwnerClaim.ok) {
  const holderPid = workspaceOwnerClaim.holder && workspaceOwnerClaim.holder.valid
    ? workspaceOwnerClaim.holder.pid : 'unverified';
  console.error('✗ StarNet refused to open this workspace because another process may own it.');
  console.error('  workspace: ' + WORKSPACES);
  console.error('  holder PID: ' + holderPid);
  console.error('  safety code: ' + String(workspaceOwnerClaim.code || 'WORKSPACE_OWNER_UNAVAILABLE'));
  console.error('  Close the other StarNet process and retry. StarNet will not risk concurrent writes.');
  process.exit(73);
}
// Synchronous and idempotent: covers ordinary returns and every process.exit path. SIGKILL/TerminateProcess
// cannot run handlers, so their valid PID-stamped claim is recovered by the next boot instead.
process.once('exit', () => { try { workspaceOwner.release(); } catch (_) {} });

// Capture lineage before this process stamps schema/cache/runtime files. It is bounded metadata only: names and
// counts, never file contents. In packaged mode we also inspect known legacy roots and verified update snapshots;
// isolated DEV/QA roots deliberately do not look sideways into the Commander's production profile.
const workspaceLineage = inspectWorkspaceLineage({
  fs: fs, path: path, platform: process.platform, workspaceRoot: WORKSPACES,
  candidateRoots: DEV_MODE ? [] : RECOVERY_CANDIDATE_ROOTS
});
const workspaceRecoveryInspection = workspaceRecovery.inspectCandidates({
  fs, path, platform: process.platform, home: os.homedir(), workspaceRoot: WORKSPACES,
  candidateRoots: DEV_MODE ? [] : RECOVERY_CANDIDATE_ROOTS
});
workspaceLineage.recovery = workspaceRecovery.publicInspection(workspaceRecoveryInspection);
// diagnostics-visible note (GET lineage/report): an auto-recovery that was SKIPPED because the target is a
// scratch root must be readable after the fact, not only in the boot log (truthful telemetry, not a hidden skip).
if (startupWorkspaceRecovery && startupWorkspaceRecovery.autoSkipped) {
  workspaceLineage.autoRecovery = { skipped: true, code: String(startupWorkspaceRecovery.code || 'AUTO_RECOVERY_TARGET_IS_SCRATCH'), reason: 'target workspace resolves under a scratch/temp root' };
}

function publicWorkspaceLineage() {
  const home = os.homedir();
  const out = JSON.parse(JSON.stringify(workspaceLineage));
  out.currentWorkspace = workspaceRecovery._internals.displayPath(out.currentWorkspace, home, path, process.platform);
  out.evidence = (out.evidence || []).map(row => Object.assign({}, row, {
    root: workspaceRecovery._internals.displayPath(row.root, home, path, process.platform)
  }));
  return out;
}

/* ---- LIVE MODEL PRICING (2026-07-31, Hermes-parity pass): wire the models.dev aggregate into the
   price snapshot so a newly-released model gets its real published rate instead of a stale family
   fallback. Strictly additive to the seatbelt: operator overrides still win, the built-in snapshot
   still answers offline, and a hostile/drifted payload is validated away (liveprices.js). The fetch
   is background + disk-cached (24h cadence) and never blocks a run. SKYNET_LIVE_PRICES=0 disables. */
const livePrices = (function () {
  try {
    if (String(ENV('LIVE_PRICES') || '').trim() === '0') return null;
    const { makeLivePrices } = require('./providers/liveprices.js');
    const prices = require('./providers/prices.js');
    const lp = makeLivePrices({ file: path.join(WORKSPACES, 'liveprices.cache.json'), now: () => Date.now() });
    prices.setLiveLookup((family, id) => lp.lookup(family, id));
    lp.refresh().catch(swallow('liveprices.refresh'));
    const t = setInterval(() => { lp.refresh().catch(swallow('liveprices.refresh')); }, 6 * 60 * 60 * 1000);
    if (t.unref) t.unref();
    return lp;
  } catch (e) { console.warn('[prices] live catalog wiring failed:', (e && e.message) || e); return null; }
})();

/* ---- P1-9 ADVANCED runtime knobs: a handful of limits that were environment-only (MAX_ITERS,
   MAX_CONCURRENT_AGENTS, the consent timeout, the cron tick) are now editable + PERSISTED so a beginner who can't
   set env vars can still tune them. PRECEDENCE is strict and disclosed in the UI: an explicit ENVIRONMENT VARIABLE
   ALWAYS WINS (a locked-down deploy stays in control), else a value SAVED here, else the built-in default. Read at
   BOOT (these feed const CAPS / gates), so a change applies on the next restart — the UI says so. Stored in a
   PROTECTED sibling of the fs jail (runtime.knobs.json). Loaded with a tiny self-contained reader (this runs before
   loadResilient/num are defined); a torn/absent file → no overrides (fail-soft to env/default). */
const RUNTIME_KNOBS_FILE = path.join(WORKSPACES, 'runtime.knobs.json');

/* ---- ATTENDED BROWSER LOGIN: the ONE durable station Chrome profile. Cookies a Commander earns by logging
   in through browser.login live here and survive run end + sidecar restarts, so later research runs browse
   signed-in. Placed as a DOTTED sibling of the agent jails: fs-tool agentIds are sanitized to [A-Za-z0-9_-],
   so no agent workspace can ever resolve into it (cookie jar stays out of model reach). Chrome cannot share
   a user-data-dir across processes, so a single-owner in-process lease guards it — sufficient because one
   sidecar per WORKSPACES dir is a hard invariant (see durable-store law). Runs that lose the race quietly
   fall back to their ephemeral per-run profile (browsing works, just signed out). */
const BROWSER_PROFILE_DIR = path.join(WORKSPACES, '.browser-profile');
let browserProfileHolder = null;   // runId of the run whose browser currently owns the durable profile
function browserProfileLeaseFor(runId) {
  return {
    dir: BROWSER_PROFILE_DIR,
    acquire: () => { if (browserProfileHolder && browserProfileHolder !== runId) return false; browserProfileHolder = runId; return true; },
    release: () => { if (browserProfileHolder === runId) browserProfileHolder = null; }
  };
}
let runtimeKnobs = (function loadRuntimeKnobsAtBoot() {
  // saveResilient writes a <file>.bak last-known-good snapshot; if the main file is torn/corrupt at boot, fall
  // back to that .bak instead of silently dropping every saved knob to env/default. (Inline .bak recovery — this
  // runs before loadResilient/readJsonResilient are usable due to declaration order, per the hardening plan.)
  function parseKnobs(raw) {
    const k = (raw && typeof raw === 'object' && raw.knobs && typeof raw.knobs === 'object') ? raw.knobs : {};
    const out = {};
    for (const key of ['maxIters', 'maxConcurrentAgents', 'consentTimeoutMs', 'cronTickMs']) {
      const v = k[key];
      if (typeof v === 'number' && isFinite(v) && v >= 0) out[key] = Math.floor(v);
    }
    return out;
  }
  try { return parseKnobs(JSON.parse(fs.readFileSync(RUNTIME_KNOBS_FILE, 'utf8'))); }
  catch (_) {
    try {
      const knobs = parseKnobs(JSON.parse(fs.readFileSync(RUNTIME_KNOBS_FILE + '.bak', 'utf8')));
      try { console.warn('[runtime-knobs] main file unreadable/corrupt at boot — recovered saved knobs from .bak'); } catch (__) {}
      return knobs;
    } catch (__) { return {}; }   // no usable main or .bak -> no overrides (fail-soft to env/default)
  }
})();
// resolve a knob: explicit env (via ENV suffix) > saved override > built-in default. envSuffix null = no env for it.
function resolveKnob(envSuffix, savedKey, def) {
  if (envSuffix) { const e = ENV(envSuffix); if (e != null && String(e).trim() !== '' && Number(e) >= 0) return Math.floor(Number(e)); }
  const s = runtimeKnobs[savedKey];
  return (typeof s === 'number' && s >= 0) ? s : def;
}
function knobEnvLocked(envSuffix) { const e = envSuffix ? ENV(envSuffix) : null; return e != null && String(e).trim() !== '' && Number(e) >= 0; }

// maxIters: optional per-run tool-turn ceiling. Default OFF (0); users/deploys may opt into one.
// maxToolBytes: the per-run tool-output FLOOR — the effective cap scales with the model's context window
// (toolBytesCapFor at the run seam) UNLESS SKYNET_MAX_TOOL_BYTES is explicitly set, which pins the cap
// absolutely (deterministic tests + locked-down deploys).
// maxUnpricedTokens: per-run TOKEN ceiling for turns no catalog/table could price on a METERED provider (the $ cap
// is blind to them). SKYNET_MAX_UNPRICED_TOKENS overrides; 0 disables. OAuth/unmetered providers are exempt.
const CAPS = { maxIters: resolveKnob('MAX_ITERS', 'maxIters', 0), maxCostUsd: 1.00, maxRepeat: 3, toolTimeoutMs: 30000, maxToolBytes: resolveKnob('MAX_TOOL_BYTES', 'maxToolBytes', 120000), maxUnpricedTokens: resolveKnob('MAX_UNPRICED_TOKENS', 'maxUnpricedTokens', 2000000) };
const MAX_TOOL_BYTES_PINNED = knobEnvLocked('MAX_TOOL_BYTES');
// Optional spend governance: per-run, per-agent, per-day, and global ceilings all default OFF.
// num() passes a parsed value through (including 0 -> UNGOVERNED via budget.js capOf, e.g. SKYNET_BUDGET_PER_DAY=0
// disables the day pool); only an empty/missing/negative/non-numeric value falls back to the default.
const num = (v, d) => { if (v == null || String(v).trim() === '') return d; const n = Number(v); return (typeof n === 'number' && !isNaN(n) && n >= 0) ? n : d; };
// Users may opt into any cap in SETTINGS → BUDGET (0/blank = no cap); environment variables
// still override for locked-down deploys. Unmetered subscription runs remain ungoverned.
const BUDGET_CAPS = {
  perRun: num(ENV('BUDGET_PER_RUN'), 0),
  perAgent: num(ENV('BUDGET_PER_AGENT'), 0),   // multi-agent fairness rail: one agent's cumulative spend (0 = ungoverned; default OFF — a lifetime cap punishes engagement, not runaways)
  perDay: num(ENV('BUDGET_PER_DAY'), 0),
  global: num(ENV('BUDGET_GLOBAL'), 0)
};
// Optional multi-agent fan-out ceiling. 0 = unlimited (the product default). See concurrency.js.
const MAX_CONCURRENT_AGENTS = resolveKnob('MAX_CONCURRENT_AGENTS', 'maxConcurrentAgents', 0);   // P1-9: env > saved > default
// Optional per-worker USD ceiling for delegated sub-runs. 0 = ungoverned.
const ORCH_PER_WORKER = num(ENV('BUDGET_PER_WORKER'), 0);
// Optional per-worker tool-turn ceiling. 0 inherits the unlimited station policy.
const ORCH_WORKER_MAX_ITERS = num(ENV('WORKER_MAX_ITERS'), 0);
// ---- MANAGED CREDITS (opt-in, config-gated). The whole managed-credit path is INERT unless STARNET_CREDITS_URL
// points at a credits backend: no payment client is built, admission stays pure BYOK, no STORE UI renders, and
// /api/credits 404s (the honesty law — a control that does nothing is a bug). When wired, a managed account can
// run without BYOK: each run RESERVES its per-run cap against the account before the model is called, and the
// unused headroom is refunded at settle (see sidecar/credits.js + sidecar/billing.js). The purchase flow is an
// external link only — this app never renders a payment form. STARNET_CREDITS_ACCOUNT names the account to bill.
const CREDITS_URL = String(ENV('CREDITS_URL') || '').trim();
const CREDITS_API_KEY = String(ENV('CREDITS_API_KEY') || '').trim();
const CREDITS_ACCOUNT = String(ENV('CREDITS_ACCOUNT') || '').trim();
const CREDITS_PURCHASE_URL = String(ENV('CREDITS_PURCHASE_URL') || '').trim();
// Floor for the low-credit warning. The EFFECTIVE threshold is max(this, the per-run cap) — see the
// makeCredits wiring below for why the cap is the meaningful half. 0 disables the warning outright.
const CREDITS_LOW_USD = (() => { const n = Number(ENV('CREDITS_LOW_USD')); return Number.isFinite(n) && n >= 0 ? n : 5; })();
// STARNET_CLOUD_URL points at the hosted StarNet Cloud service (accounts + credits + device linking). When set,
// the STORE offers a LINK STATION flow that pairs this station to an account and configures credits LIVE (no env,
// no restart). Empty => the feature is absent (honesty law): the /api/credits/link/* routes 404 and no LINK card
// renders. Env CREDITS_* config still wins over a linked device (operator override / backward compat).
//
// THE SHIPPED DEFAULT AND ITS SWITCH. A packaged build sets no env, so with an env-only lookup the entire
// subscription is invisible to every user who ever installs StarNet — the feature would exist and reach nobody.
// The default therefore lives in the binary, behind ONE flag: while CLOUD_LIVE is false the station behaves
// exactly as if no cloud existed, because offering LINK STATION against a service that is not deployed yet
// would be a button that promises an account we cannot actually create. This is the same gate, and must be
// flipped in the same breath, as `CREDITS.live` in website/site.js — the site's buy buttons and the app's link
// button have to tell the same story on the same day. An explicit STARNET_CLOUD_URL always wins, so operators
// and this repo's own live tests can point at a local service without touching the flag.
const CLOUD_LIVE = true;                                    // ← launch switch: flip WITH website/site.js CREDITS.live
const CLOUD_URL_DEFAULT = 'https://account.starnetos.com';   // the deployed StarNet Cloud (see starnet-cloud)
const CLOUD_URL = String(ENV('CLOUD_URL') || (CLOUD_LIVE ? CLOUD_URL_DEFAULT : '')).trim();
// The linked station's device token, injected by the DESKTOP from the OS keychain at spawn (keychain account
// "credits:device"). It is a bearer credential that spends money, so the desktop adopts it out of
// .secrets/credits.json and strips the file copy; this env var is how it gets back in. Unset in a bare/dev
// sidecar, where the token simply stays in the file as before — see sidecar/credits-link.js header.
const CREDITS_TOKEN = String(ENV('CREDITS_TOKEN') || '').trim();
// a live permission.prompt left unanswered this long auto-denies (never hangs a run). P1-9: env
// STARNET_CONSENT_TIMEOUT_MS > a UI-saved override > the 120s default; the frozen resolve keeps it constant per boot.
const CONSENT_TIMEOUT_MS = resolveKnob('CONSENT_TIMEOUT_MS', 'consentTimeoutMs', 120000);
// EL-11 FIX 1c: when the browser ATTESTS a consent prompt is rendered to a human (POST /api/consent/ack —
// fired for the active card AND the new background toast/rail marker), the deny deadline extends ONCE to this
// bound. Unattended surfaces never ack, so their fail-closed floor above is untouched; an AFK human still
// fail-closes at this bound (never indefinite). 5× the floor, hard-capped at 15 minutes.
const CONSENT_ACK_EXTEND_MS = Math.min(CONSENT_TIMEOUT_MS * 5, 900000);
// ---- cron / scheduled routines (autonomous, OPT-IN). The whole subsystem is INERT unless SKYNET_CRON_ENABLED
// is set: no timer is armed, no run is fired, and the browser path is byte-identical. A fire uses the same
// provider seam as /api/run: OpenRouter needs the live BYOK key (runtimeKey), while Codex uses the protected
// ChatGPT OAuth token. A job with no model falls back to the selected agent model or SKYNET_DEFAULT_MODEL;
// absent model/credentials, a due job no-capability-skips rather than firing. Cadence + the self-healing lease
// ceiling are env-tunable. The fire's consent surface is 'autonomous' (default-deny ungranted mutation).
const CRON_ENABLED = /^(1|true|yes|on)$/i.test(String(ENV('CRON_ENABLED') || '').trim());
const CRON_TICK_MS = resolveKnob('CRON_TICK_MS', 'cronTickMs', 60000);   // P1-9: env > saved > default
// Host IANA timezone, captured ONCE at boot as a boot-frozen constant (G4.1). A cron schedule with no
// explicit tz fires on this LOCAL wall-clock (so "0 9 * * *" means 09:00 here and shifts across DST),
// while the pure cron-math (sidecar/cron.js) stays determinism-clean by receiving this as an INJECTED
// defaultTz rather than reading the ambient clock itself. Override with SKYNET_CRON_TZ (e.g. for a
// headless server that should run routines in a specific zone); an invalid value falls back to UTC so a
// typo never wedges the scheduler. A schedule's OWN tz always wins over this default.
const CRON_HOST_TZ = (function () {
  const override = String(ENV('CRON_TZ') || '').trim();
  const candidate = override || (function () {
    try { return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'; } catch (_) { return 'UTC'; }
  })();
  return cron.isValidTz(candidate) ? (candidate || 'UTC') : 'UTC';
})();
const CRON_MAX_RUN_MS = num(ENV('CRON_MAX_RUN_MS'), 480000);   // operational lease/timeout, independent of user-work quotas
// Optional routine-specific concurrency ceiling. The station-wide opt-in agent ceiling still applies.
const CRON_MAX_PARALLEL = num(ENV('CRON_MAX_PARALLEL'), 0);
// terminal failures IN A ROW before a recurring routine auto-pauses (0 = never). Default 5.
const CRON_MAX_CONSECUTIVE_FAILURES = num(ENV('CRON_MAX_CONSECUTIVE_FAILURES'), 5);
// NS-0 LEASE HEARTBEAT knobs. The lease sweep + one-shot fireClaim now reclaim on a STALE HEARTBEAT rather than a
// fixed wall-clock age, so a genuinely-long run that keeps emitting progress fires exactly once (the duplicate-fire
// fix). CRON_STALENESS_MULT scales maxRunMs into the no-heartbeat staleness ceiling (default 1 = pre-NS-0 timing for
// a silent run); CRON_HEARTBEAT_STALE_MS overrides it outright; CRON_DURABLE_HEARTBEAT_MS throttles the durable
// one-shot heartbeat write (default = staleMs/4) so the hot token stream never fsyncs on every delta.
const CRON_STALENESS_MULT = (function () { const n = parseFloat(ENV('CRON_STALENESS_MULT')); return (Number.isFinite(n) && n > 0) ? n : 1; })();
const CRON_HEARTBEAT_STALE_MS = num(ENV('CRON_HEARTBEAT_STALE_MS'), Math.round(CRON_MAX_RUN_MS * CRON_STALENESS_MULT));
const CRON_DURABLE_HEARTBEAT_MS = num(ENV('CRON_DURABLE_HEARTBEAT_MS'), Math.max(1, Math.round(CRON_HEARTBEAT_STALE_MS / 4)));
// ---- NIGHT SHIFT (NS-1): the server-owned idle-autonomy driver. RESTART-SAFE replacement for the frontend
// autopilot loop (which died on sleep/throttle/restart). While the Commander is AWAY and the dial permits acting,
// it attempts one autonomous beat every ~beatInterval, leash-capped (leash ENFORCED here, not in localStorage),
// day-rolling, E-STOP-aware. INERT-when-off invariant: the timer arms only when SKYNET_NIGHTSHIFT_ENABLED (env)
// OR the posture's initiative is ≥ 'leash' at boot — with neither, no timer is ever constructed and the path is
// byte-identical. The tick cadence is FAST (like cron's 60s) so a beat becomes eligible promptly once away+cooldown
